patch:
diff --git a/Zend/zend_execute.c b/Zend/zend_execute.c
--- a/Zend/zend_execute.c
+++ b/Zend/zend_execute.c
@@ -855,7 +855,7 @@ ZEND_COLD zend_never_inline void zend_verify_property_type_error(const zend_prop
 	if (EG(exception)) {
 		return;
 	}

-	type_str = zend_type_to_string(info->type);
+	type_str = zend_type_to_string_resolved(info->type, info->ce);
 	zend_type_error("Cannot assign %s to property %s::$%s of type %s",
 		zend_zval_value_name(property),
 		ZSTR_VAL(info->ce->name),
diff --git a/Zend/tests/type_declarations/typed_properties_anonymous_self_error.phpt b/Zend/tests/type_declarations/typed_properties_anonymous_self_error.phpt
new file mode 100644
--- /dev/null
+++ b/Zend/tests/type_declarations/typed_properties_anonymous_self_error.phpt
@@ -0,0 +1,14 @@
+--TEST--
+Anonymous class self typed property assignment reports TypeError
+--FILE--
+<?php
+$foo = new class {
+    public self $v;
+};
+try {
+    $foo->v = 0;
+} catch (TypeError $e) {
+    echo $e->getMessage(), \

;
+}
+?>
+--EXPECT--
+Cannot assign int to property class@anonymous::$v of type class@anonymous
